import{_ as e,o as l,c as n,a0 as s}from"./chunks/framework.jwovEGr5.js";const b=JSON.parse('{"title":"心肺复苏","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"中山大学/新生课程/心肺复苏.md","filePath":"中山大学/新生课程/心肺复苏.md"}'),p={name:"中山大学/新生课程/心肺复苏.md"};function i(t,a,o,r,h,c){return l(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="心肺复苏" tabindex="-1">心肺复苏 <a class="header-anchor" href="#心肺复苏" aria-label="Permalink to &quot;心肺复苏&quot;">​</a></h1><p>课程时间：2026.8.21 16:45~17:45</p><p>主讲：余涛</p><h2 id="心搏骤停的定义与流行病学" tabindex="-1">心搏骤停的定义与流行病学 <a class="header-anchor" href="#心搏骤停的定义与流行病学" aria-label="Permalink to &quot;心搏骤停的定义与流行病学&quot;">​</a></h2><p>指心脏泵血功能突然终止，全身血液循环中断，迅速出现意识丧失、大动脉搏动消失、呼吸停止或濒死喘息</p><p>一些名词解释</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>心源性猝死SCD：心脏原因所致，急性症状起病1小时内发生的死亡，是心搏骤停抢救失败的结局。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BLS基础生命支持：现场徒手抢救，胸外按压、开放气道、人工呼吸、AED除颤，不需要高级设备。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ACLS高级心血管生命支持：专业人员实施，建立高级气道、给药、电除颤、循环支持。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ROSC自主循环恢复：恢复可触及的大动脉搏动，恢复有效心输出量，复苏成功标志。</span></span></code></pre></div><h2 id="_1-心搏骤停的原因" tabindex="-1">1.心搏骤停的原因 <a class="header-anchor" href="#_1-心搏骤停的原因" aria-label="Permalink to &quot;1.心搏骤停的原因&quot;">​</a></h2><p>呼吸、意外、电解质紊乱、创伤</p><h2 id="_2-心跳骤停的判断" tabindex="-1">2.心跳骤停的判断 <a class="header-anchor" href="#_2-心跳骤停的判断" aria-label="Permalink to &quot;2.心跳骤停的判断&quot;">​</a></h2><ol><li>判断患者意识</li><li>判断呼吸</li></ol><p>心搏骤停的识别</p><h2 id="bls基础生命支持-生存链、c‐a‐b流程" tabindex="-1">BLS基础生命支持：生存链、C‑A‑B流程 <a class="header-anchor" href="#bls基础生命支持-生存链、c‐a‐b流程" aria-label="Permalink to &quot;BLS基础生命支持：生存链、C‑A‑B流程&quot;">​</a></h2><p>成人院外生存链：</p><p>识别呼救→旁观者CPR→早期AED除颤→高级急救→ROSC后综合救治→康复</p><blockquote><p>临床原则：即使发生肋骨骨折，也不能停止按压，生存获益远大于损伤。</p></blockquote><h3 id="胸部按压-c" tabindex="-1">胸部按压 C <a class="header-anchor" href="#胸部按压-c" aria-label="Permalink to &quot;胸部按压 C&quot;">​</a></h3><p>100~120次每分钟</p><p>成人深度：5‑6cm，禁止＞6cm</p><h3 id="开放气道-a" tabindex="-1">开放气道 A <a class="header-anchor" href="#开放气道-a" aria-label="Permalink to &quot;开放气道 A&quot;">​</a></h3><p>仰头抬颏法：一手压额头，另一手上抬下颌，打开气道；怀疑颈椎损伤用托颌法</p><h3 id="人工呼吸-b" tabindex="-1">人工呼吸 B <a class="header-anchor" href="#人工呼吸-b" aria-label="Permalink to &quot;人工呼吸 B&quot;">​</a></h3><p>口对面膜、口对面罩人工呼吸（防止传染性疾病）</p><p>单纯胸外按压的心肺复苏</p><h2 id="除颤" tabindex="-1">除颤 <a class="header-anchor" href="#除颤" aria-label="Permalink to &quot;除颤&quot;">​</a></h2><p>原理</p><p>心脏的各个地方肌肉运动不同步，电击先让心肌全部暂停，再恢复正常跳动</p><p>除颤仪</p><ol><li>除颤器</li><li>自动体外除颤器（AED）</li></ol><p>使用方法：打开电源、贴电极片（右胸上方、左胸侧面肋骨处）、所有人离开，机器分析心律、提示除颤时再次确认离开，按下放电；</p><p>放电后继续心肺复苏</p><h2 id="终止心肺复苏指征" tabindex="-1">终止心肺复苏指征 <a class="header-anchor" href="#终止心肺复苏指征" aria-label="Permalink to &quot;终止心肺复苏指征&quot;">​</a></h2><p>满足其一即可终止：</p><ol><li>自主循环恢复ROSC：恢复自主呼吸、可触及大动脉搏动，生命体征稳定</li><li>现场专业人员确认生物学死亡：尸僵、尸斑、严重躯体毁损，瞳孔散大固定无反射</li><li>规范高质量 CPR持续≥30min，始终无ROSC，排除低温、中毒、电解质紊乱等可逆因素</li></ol>`,34)])])}const u=e(p,[["render",i]]);export{b as __pageData,u as default};
